INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-07-01', 'lesson-phrasal-b1-07', 1, 'phrasal', 'She made up an excuse.', 'Ela inventou uma desculpa.', '/ʃiː meɪd ʌp ən ɪkˈskjuːz/', '"Make up" = inventar (história, desculpa). Separável.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"made","pos":"verb","ipa":"/meɪd/","gloss":"fez, feito"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"excuse","pos":"verb","ipa":"/ɪkˈskjuːz/","gloss":"desculpar (excuse me = com licença)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-07-02', 'lesson-phrasal-b1-07', 2, 'phrasal', 'They argued, but they made up later.', 'Eles brigaram, mas fizeram as pazes depois.', '/ðeɪ ˈɑːrɡjuːd bʌt ðeɪ meɪd ʌp ˈleɪtər/', '"Make up" (sem objeto) = fazer as pazes.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"argued","pos":"verb","ipa":"/ˈɑːrɡjuːd/","gloss":"discutiram, brigaram"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"made","pos":"verb","ipa":"/meɪd/","gloss":"fez, feito"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"later","pos":"adverb","ipa":"/ˈleɪtər/","gloss":"mais tarde"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-07-03', 'lesson-phrasal-b1-07', 3, 'phrasal', 'I can''t make out what he is saying.', 'Não consigo entender o que ele está dizendo.', '/aɪ kænt meɪk aʊt wʌt hiː ɪz ˈseɪɪŋ/', '"Make out" = distinguir, entender (som, letra).', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"saying","pos":"verb","ipa":"/ˈseɪɪŋ/","gloss":"dizendo"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-07-04', 'lesson-phrasal-b1-07', 4, 'phrasal', 'I will make up for lost time.', 'Vou compensar o tempo perdido.', '/aɪ wɪl meɪk ʌp fɔːr lɔːst taɪm/', '"Make up for" = compensar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"lost","pos":"adjective","ipa":"/lɔːst/","gloss":"perdido; perdeu"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-07-05', 'lesson-phrasal-b1-07', 5, 'phrasal', 'Women make up half of the team.', 'Mulheres formam metade do time.', '/ˈwɪmɪn meɪk ʌp hæf ʌv ðə tiːm/', '"Make up" = compor, formar.', '[]'::jsonb, '[{"surface":"Women","pos":"noun","ipa":"/ˈwɪmɪn/","gloss":"mulheres"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"half","pos":"noun","ipa":"/hæf/","gloss":"metade, meio"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"team","pos":"noun","ipa":"/tiːm/","gloss":"time, equipe"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-07-06', 'lesson-phrasal-b1-07', 6, 'phrasal', 'We made it to the airport on time.', 'Conseguimos chegar ao aeroporto a tempo.', '/wiː meɪd ɪt tuː ðə ˈɛrpɔːrt ɑːn taɪm/', '"Make it" = conseguir chegar, ter sucesso.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"made","pos":"verb","ipa":"/meɪd/","gloss":"fez, feito"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"airport","pos":"noun","ipa":"/ˈɛrpɔːrt/","gloss":"aeroporto"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-07-07', 'lesson-phrasal-b1-07', 7, 'phrasal', 'Can you make sure the door is locked?', 'Pode confirmar que a porta está trancada?', '/kæn juː meɪk ʃʊr ðə dɔːr ɪz lɑːkt/', '"Make sure" = garantir, conferir.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"sure","pos":"adjective","ipa":"/ʃʊr/","gloss":"claro; certo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"locked","pos":"adjective","ipa":"/lɑːkt/","gloss":"trancado"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-07-08', 'lesson-phrasal-b1-07', 8, 'phrasal', 'Make yourself at home.', 'Fique à vontade.', '/meɪk jərˈsɛlf æt hoʊm/', 'Expressão fixa para receber visita.', '[]'::jsonb, '[{"surface":"Make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"yourself","pos":"pronoun","ipa":"/jərˈsɛlf/","gloss":"você mesmo"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-07-09', 'lesson-phrasal-b1-07', 9, 'phrasal', 'Let''s make the most of the weekend.', 'Vamos aproveitar ao máximo o fim de semana.', '/lɛts meɪk ðə moʊst ʌv ðə ˈwiːkɛnd/', '"Make the most of" = aproveitar ao máximo.', '[]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"most","pos":"determiner","ipa":"/moʊst/","gloss":"o máximo, a maioria"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"weekend","pos":"noun","ipa":"/ˈwiːkɛnd/","gloss":"fim de semana"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-07-10', 'lesson-phrasal-b1-07', 10, 'phrasal', 'I need to make up my mind.', 'Preciso me decidir.', '/aɪ niːd tuː meɪk ʌp maɪ maɪnd/', '"Make up one''s mind" = decidir-se.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"mind","pos":"verb","ipa":"/maɪnd/","gloss":"se importar"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-08-01', 'lesson-phrasal-b1-08', 1, 'phrasal', 'My car broke down on the highway.', 'Meu carro quebrou na rodovia.', '/maɪ kɑːr broʊk daʊn ɑːn ðə ˈhaɪweɪ/', '"Break down" = quebrar (máquina, veículo).', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"broke","pos":"verb","ipa":"/broʊk/","gloss":"quebrou"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"highway","pos":"noun","ipa":"/ˈhaɪweɪ/","gloss":"rodovia"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-08-02', 'lesson-phrasal-b1-08', 2, 'phrasal', 'She broke down and cried.', 'Ela desabou e chorou.', '/ʃiː broʊk daʊn ænd kraɪd/', '"Break down" (pessoa) = desmoronar emocionalmente.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"broke","pos":"verb","ipa":"/broʊk/","gloss":"quebrou"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"cried","pos":"verb","ipa":"/kraɪd/","gloss":"chorou"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-08-03', 'lesson-phrasal-b1-08', 3, 'phrasal', 'They broke up after two years.', 'Eles terminaram depois de dois anos.', '/ðeɪ broʊk ʌp ˈæftər tuː jɪrz/', '"Break up (with)" = terminar namoro.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"broke","pos":"verb","ipa":"/broʊk/","gloss":"quebrou"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-08-04', 'lesson-phrasal-b1-08', 4, 'phrasal', 'Someone broke into our house.', 'Alguém arrombou nossa casa.', '/ˈsʌmwʌn broʊk ˈɪntuː aʊər haʊs/', '"Break into" = invadir, arrombar. Não separável.', '[]'::jsonb, '[{"surface":"Someone","pos":"pronoun","ipa":"/ˈsʌmwʌn/","gloss":"alguém"},{"surface":"broke","pos":"verb","ipa":"/broʊk/","gloss":"quebrou"},{"surface":"into","pos":"preposition","ipa":"/ˈɪntuː/","gloss":"para dentro de"},{"surface":"our","pos":"determiner","ipa":"/aʊər/","gloss":"nosso"},{"surface":"house","pos":"noun","ipa":"/haʊs/","gloss":"casa"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-08-05', 'lesson-phrasal-b1-08', 5, 'phrasal', 'A fire broke out in the kitchen.', 'Começou um incêndio na cozinha.', '/ə ˈfaɪər broʊk aʊt ɪn ðə ˈkɪtʃən/', '"Break out" = começar de repente (fogo, guerra, doença).', '[]'::jsonb, '[{"surface":"A","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"fire","pos":"noun","ipa":"/ˈfaɪər/","gloss":"fogo, incêndio"},{"surface":"broke","pos":"verb","ipa":"/broʊk/","gloss":"quebrou"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"kitchen","pos":"noun","ipa":"/ˈkɪtʃən/","gloss":"cozinha"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-08-06', 'lesson-phrasal-b1-08', 6, 'phrasal', 'Let''s break the task down into steps.', 'Vamos dividir a tarefa em etapas.', '/lɛts breɪk ðə tæsk daʊn ˈɪntuː stɛps/', '"Break down" (com objeto) = dividir em partes. Separável.', '[]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"break","pos":"noun","ipa":"/breɪk/","gloss":"pausa, intervalo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"task","pos":"noun","ipa":"/tæsk/","gloss":"tarefa"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"into","pos":"preposition","ipa":"/ˈɪntuː/","gloss":"para dentro de"},{"surface":"steps","pos":"noun","ipa":"/stɛps/","gloss":"passos"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-08-07', 'lesson-phrasal-b1-08', 7, 'phrasal', 'The meeting broke up at five.', 'A reunião terminou às cinco.', '/ðə ˈmiːtɪŋ broʊk ʌp æt faɪv/', '"Break up" (grupo) = dispersar, acabar.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"broke","pos":"verb","ipa":"/broʊk/","gloss":"quebrou"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-08-08', 'lesson-phrasal-b1-08', 8, 'phrasal', 'He broke the news to his parents.', 'Ele contou a notícia aos pais.', '/hiː broʊk ðə nuːz tuː hɪz ˈpɛrənts/', '"Break the news" = dar uma notícia difícil.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"broke","pos":"verb","ipa":"/broʊk/","gloss":"quebrou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"news","pos":"noun","ipa":"/nuːz/","gloss":"notícia(s)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"his","pos":"determiner","ipa":"/hɪz/","gloss":"dele"},{"surface":"parents","pos":"noun","ipa":"/ˈpɛrənts/","gloss":"pais (pai e mãe)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-08-09', 'lesson-phrasal-b1-08', 9, 'phrasal', 'Let''s take a break.', 'Vamos fazer uma pausa.', '/lɛts teɪk ə breɪk/', '"Break" como substantivo = pausa.', '[]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"break","pos":"noun","ipa":"/breɪk/","gloss":"pausa, intervalo"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-08-10', 'lesson-phrasal-b1-08', 10, 'phrasal', 'She broke the record.', 'Ela bateu o recorde.', '/ʃiː broʊk ðə ˈrɛkərd/', '"Break a record" = bater um recorde.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"broke","pos":"verb","ipa":"/broʊk/","gloss":"quebrou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"record","pos":"noun","ipa":"/ˈrɛkərd/","gloss":"recorde"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-09-01', 'lesson-phrasal-b1-09', 1, 'phrasal', 'Don''t bring up politics at dinner.', 'Não puxe o assunto política no jantar.', '/doʊnt brɪŋ ʌp ˈpɑːlətɪks æt ˈdɪnər/', '"Bring up" = mencionar, puxar assunto. Separável.', '[]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"bring","pos":"verb","ipa":"/brɪŋ/","gloss":"trazer"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"politics","pos":"noun","ipa":"/ˈpɑːlətɪks/","gloss":"política"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-09-02', 'lesson-phrasal-b1-09', 2, 'phrasal', 'She was brought up by her grandparents.', 'Ela foi criada pelos avós.', '/ʃiː wɑːz brɔːt ʌp baɪ hɜːr ˈɡrænpɛrənts/', '"Bring up" (criança) = criar, educar.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"brought","pos":"verb","ipa":"/brɔːt/","gloss":"trouxe, levou"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"grandparents","pos":"noun","ipa":"/ˈɡrænpɛrənts/","gloss":"avós"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-09-03', 'lesson-phrasal-b1-09', 3, 'phrasal', 'This song brings back memories.', 'Esta música traz lembranças.', '/ðɪs sɔːŋ brɪŋz bæk ˈmɛməriz/', '"Bring back" = trazer de volta, lembrar.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"song","pos":"noun","ipa":"/sɔːŋ/","gloss":"canção, música"},{"surface":"brings","pos":"verb","ipa":"/brɪŋz/","gloss":"traz"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"memories","pos":"noun","ipa":"/ˈmɛməriz/","gloss":"lembranças"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-09-04', 'lesson-phrasal-b1-09', 4, 'phrasal', 'Please bring the book back tomorrow.', 'Por favor, devolva o livro amanhã.', '/pliːz brɪŋ ðə bʊk bæk təˈmɑːroʊ/', '"Bring back" = devolver. Separável.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"bring","pos":"verb","ipa":"/brɪŋ/","gloss":"trazer"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-09-05', 'lesson-phrasal-b1-09', 5, 'phrasal', 'The new law brought about many changes.', 'A nova lei provocou muitas mudanças.', '/ðə nuː lɔː brɔːt əˈbaʊt ˈmɛni ˈtʃeɪndʒɪz/', '"Bring about" = causar, provocar. Formal.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"law","pos":"noun","ipa":"/lɔː/","gloss":"lei"},{"surface":"brought","pos":"verb","ipa":"/brɔːt/","gloss":"trouxe, levou"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"many","pos":"determiner","ipa":"/ˈmɛni/","gloss":"muitos (how many)"},{"surface":"changes","pos":"noun","ipa":"/ˈtʃeɪndʒɪz/","gloss":"mudanças"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-09-06', 'lesson-phrasal-b1-09', 6, 'phrasal', 'We need to bring down costs.', 'Precisamos reduzir custos.', '/wiː niːd tuː brɪŋ daʊn kɔːsts/', '"Bring down" = reduzir.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"bring","pos":"verb","ipa":"/brɪŋ/","gloss":"trazer"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"costs","pos":"verb","ipa":"/kɔːsts/","gloss":"custa"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-09-07', 'lesson-phrasal-b1-09', 7, 'phrasal', 'Can you bring the meeting forward to Monday?', 'Pode antecipar a reunião para segunda?', '/kæn juː brɪŋ ðə ˈmiːtɪŋ ˈfɔːrwərd tuː ˈmʌndeɪ/', '"Bring forward" = antecipar.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"bring","pos":"verb","ipa":"/brɪŋ/","gloss":"trazer"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"forward","pos":"adverb","ipa":"/ˈfɔːrwərd/","gloss":"adiante (look forward)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"Monday","pos":"proper noun","ipa":"/ˈmʌndeɪ/","gloss":"segunda-feira"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-09-08', 'lesson-phrasal-b1-09', 8, 'phrasal', 'What brings you here today?', 'O que te traz aqui hoje?', '/wʌt brɪŋz juː hɪr təˈdeɪ/', 'Pergunta de abertura, simpática.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"brings","pos":"verb","ipa":"/brɪŋz/","gloss":"traz"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-09-09', 'lesson-phrasal-b1-09', 9, 'phrasal', 'Bring it on!', 'Pode vir!', '/brɪŋ ɪt ɑːn/', 'Informal: aceitar um desafio.', '[]'::jsonb, '[{"surface":"Bring","pos":"verb","ipa":"/brɪŋ/","gloss":"trazer"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-09-10', 'lesson-phrasal-b1-09', 10, 'phrasal', 'Bring a jacket, it gets cold at night.', 'Traga uma jaqueta, esfria à noite.', '/brɪŋ ə ˈdʒækɪt ɪt ɡɛts koʊld æt naɪt/', '"Bring" (sem partícula) = trazer.', '[]'::jsonb, '[{"surface":"Bring","pos":"verb","ipa":"/brɪŋ/","gloss":"trazer"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"jacket","pos":"noun","ipa":"/ˈdʒækɪt/","gloss":"jaqueta"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"gets","pos":"verb","ipa":"/ɡɛts/","gloss":"fica"},{"surface":"cold","pos":"noun","ipa":"/koʊld/","gloss":"resfriado; frio"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-10-01', 'lesson-phrasal-b1-10', 1, 'phrasal', 'We''ve run out of coffee.', 'Acabou o café.', '/wiːv rʌn aʊt ʌv ˈkɔːfi/', '"Run out of" = ficar sem.', '[]'::jsonb, '[{"surface":"We''ve","pos":"pronoun","ipa":"/wiːv/","gloss":"nós temos (we have)"},{"surface":"run","pos":"verb","ipa":"/rʌn/","gloss":"correr; administrar"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-10-02', 'lesson-phrasal-b1-10', 2, 'phrasal', 'I ran into an old friend yesterday.', 'Encontrei um velho amigo por acaso ontem.', '/aɪ ræn ˈɪntuː ən oʊld frɛnd ˈjɛstərdeɪ/', '"Run into" = esbarrar em alguém por acaso.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"ran","pos":"verb","ipa":"/ræn/","gloss":"correu"},{"surface":"into","pos":"preposition","ipa":"/ˈɪntuː/","gloss":"para dentro de"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"},{"surface":"friend","pos":"noun","ipa":"/frɛnd/","gloss":"amigo, amiga"},{"surface":"yesterday","pos":"adverb","ipa":"/ˈjɛstərdeɪ/","gloss":"ontem"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-10-03', 'lesson-phrasal-b1-10', 3, 'phrasal', 'The dog ran away.', 'O cachorro fugiu.', '/ðə dɔːɡ ræn əˈweɪ/', '"Run away" = fugir.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"dog","pos":"noun","ipa":"/dɔːɡ/","gloss":"cachorro"},{"surface":"ran","pos":"verb","ipa":"/ræn/","gloss":"correu"},{"surface":"away","pos":"adverb","ipa":"/əˈweɪ/","gloss":"embora; (right away) já"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-10-04', 'lesson-phrasal-b1-10', 4, 'phrasal', 'Let me run over the main points.', 'Deixa eu repassar os pontos principais.', '/lɛt miː rʌn ˈoʊvər ðə meɪn pɔɪnts/', '"Run over" = repassar rapidamente; também atropelar.', '[]'::jsonb, '[{"surface":"Let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"run","pos":"verb","ipa":"/rʌn/","gloss":"correr; administrar"},{"surface":"over","pos":"preposition","ipa":"/ˈoʊvər/","gloss":"por cima; superado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"main","pos":"adjective","ipa":"/meɪn/","gloss":"principal"},{"surface":"points","pos":"noun","ipa":"/pɔɪnts/","gloss":"pontos"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-10-05', 'lesson-phrasal-b1-10', 5, 'phrasal', 'The meeting ran over by twenty minutes.', 'A reunião passou vinte minutos do horário.', '/ðə ˈmiːtɪŋ ræn ˈoʊvər baɪ ˈtwɛnti ˈmɪnɪts/', '"Run over" (tempo) = passar do horário.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"ran","pos":"verb","ipa":"/ræn/","gloss":"correu"},{"surface":"over","pos":"preposition","ipa":"/ˈoʊvər/","gloss":"por cima; superado"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"twenty","pos":"numeral","ipa":"/ˈtwɛnti/","gloss":"vinte"},{"surface":"minutes","pos":"noun","ipa":"/ˈmɪnɪts/","gloss":"minutos"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-10-06', 'lesson-phrasal-b1-10', 6, 'phrasal', 'Time is running out.', 'O tempo está acabando.', '/taɪm ɪz ˈrʌnɪŋ aʊt/', '"Run out" (sem "of") = estar acabando.', '[]'::jsonb, '[{"surface":"Time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"running","pos":"verb","ipa":"/ˈrʌnɪŋ/","gloss":"ficando (running late)"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-10-07', 'lesson-phrasal-b1-10', 7, 'phrasal', 'Can you run this by your manager?', 'Pode passar isso pelo seu gerente?', '/kæn juː rʌn ðɪs baɪ jʊr ˈmænɪdʒər/', '"Run by" = consultar alguém antes de decidir.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"run","pos":"verb","ipa":"/rʌn/","gloss":"correr; administrar"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"manager","pos":"noun","ipa":"/ˈmænɪdʒər/","gloss":"gerente"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-10-08', 'lesson-phrasal-b1-10', 8, 'phrasal', 'We ran into some problems.', 'Tivemos alguns problemas.', '/wiː ræn ˈɪntuː sʌm ˈprɑːbləmz/', '"Run into problems" = encontrar problemas.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"ran","pos":"verb","ipa":"/ræn/","gloss":"correu"},{"surface":"into","pos":"preposition","ipa":"/ˈɪntuː/","gloss":"para dentro de"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"problems","pos":"noun","ipa":"/ˈprɑːbləmz/","gloss":"problemas"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-10-09', 'lesson-phrasal-b1-10', 9, 'phrasal', 'She runs a small business.', 'Ela administra um pequeno negócio.', '/ʃiː rʌnz ə smɔːl ˈbɪznəs/', '"Run" (sem partícula) = administrar.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"runs","pos":"verb","ipa":"/rʌnz/","gloss":"administra; corre"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"},{"surface":"business","pos":"noun","ipa":"/ˈbɪznəs/","gloss":"negócio, empresa"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-10-10', 'lesson-phrasal-b1-10', 10, 'phrasal', 'It runs in the family.', 'É de família.', '/ɪt rʌnz ɪn ðə ˈfæməli/', 'Expressão: característica herdada.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"runs","pos":"verb","ipa":"/rʌnz/","gloss":"administra; corre"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"family","pos":"noun","ipa":"/ˈfæməli/","gloss":"família"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-11-01', 'lesson-phrasal-b1-11', 1, 'phrasal', 'Can you help me set up the projector?', 'Pode me ajudar a montar o projetor?', '/kæn juː hɛlp miː sɛt ʌp ðə prəˈdʒɛktər/', '"Set up" = montar, configurar. Separável.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"set","pos":"verb","ipa":"/sɛt/","gloss":"definir"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"projector","pos":"noun","ipa":"/prəˈdʒɛktər/","gloss":"projetor"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-11-02', 'lesson-phrasal-b1-11', 2, 'phrasal', 'She set up her own company.', 'Ela abriu a própria empresa.', '/ʃiː sɛt ʌp hɜːr oʊn ˈkʌmpəni/', '"Set up" = fundar, criar.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"set","pos":"verb","ipa":"/sɛt/","gloss":"definir"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"own","pos":"verb","ipa":"/oʊn/","gloss":"ser dono, responsável"},{"surface":"company","pos":"noun","ipa":"/ˈkʌmpəni/","gloss":"empresa"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-11-03', 'lesson-phrasal-b1-11', 3, 'phrasal', 'We set off early in the morning.', 'Saímos cedo de manhã.', '/wiː sɛt ɔːf ˈɜːrli ɪn ðə ˈmɔːrnɪŋ/', '"Set off" = partir (viagem).', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"set","pos":"verb","ipa":"/sɛt/","gloss":"definir"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"morning","pos":"noun","ipa":"/ˈmɔːrnɪŋ/","gloss":"manhã"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-11-04', 'lesson-phrasal-b1-11', 4, 'phrasal', 'The smoke set off the alarm.', 'A fumaça disparou o alarme.', '/ðə smoʊk sɛt ɔːf ðə əˈlɑːrm/', '"Set off" (com objeto) = disparar.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"smoke","pos":"verb","ipa":"/smoʊk/","gloss":"fumar"},{"surface":"set","pos":"verb","ipa":"/sɛt/","gloss":"definir"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"alarm","pos":"noun","ipa":"/əˈlɑːrm/","gloss":"despertador, alarme"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-11-05', 'lesson-phrasal-b1-11', 5, 'phrasal', 'They set out to change the world.', 'Eles se propuseram a mudar o mundo.', '/ðeɪ sɛt aʊt tuː tʃeɪndʒ ðə wɜːrld/', '"Set out to" = ter como objetivo.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"set","pos":"verb","ipa":"/sɛt/","gloss":"definir"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"world","pos":"noun","ipa":"/wɜːrld/","gloss":"mundo"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-11-06', 'lesson-phrasal-b1-11', 6, 'phrasal', 'The storm set us back two days.', 'A tempestade nos atrasou dois dias.', '/ðə stɔːrm sɛt ʌs bæk tuː deɪz/', '"Set back" = atrasar. Substantivo: "setback" = revés.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"storm","pos":"noun","ipa":"/stɔːrm/","gloss":"tempestade"},{"surface":"set","pos":"verb","ipa":"/sɛt/","gloss":"definir"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"days","pos":"noun","ipa":"/deɪz/","gloss":"dias"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-11-07', 'lesson-phrasal-b1-11', 7, 'phrasal', 'Set the alarm for six.', 'Coloque o despertador para as seis.', '/sɛt ðə əˈlɑːrm fɔːr sɪks/', '"Set an alarm" = programar o despertador.', '[]'::jsonb, '[{"surface":"Set","pos":"verb","ipa":"/sɛt/","gloss":"definir"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"alarm","pos":"noun","ipa":"/əˈlɑːrm/","gloss":"despertador, alarme"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"six","pos":"numeral","ipa":"/sɪks/","gloss":"seis"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-11-08', 'lesson-phrasal-b1-11', 8, 'phrasal', 'Let''s set a date for the meeting.', 'Vamos marcar uma data para a reunião.', '/lɛts sɛt ə deɪt fɔːr ðə ˈmiːtɪŋ/', '"Set a date" = marcar data.', '[]'::jsonb, '[{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"set","pos":"verb","ipa":"/sɛt/","gloss":"definir"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"date","pos":"noun","ipa":"/deɪt/","gloss":"data"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-11-09', 'lesson-phrasal-b1-11', 9, 'phrasal', 'The sun sets at seven.', 'O sol se põe às sete.', '/ðə sʌn sɛts æt ˈsɛvən/', '"Set" (sol) = pôr-se.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"sun","pos":"noun","ipa":"/sʌn/","gloss":"sol"},{"surface":"sets","pos":"verb","ipa":"/sɛts/","gloss":"põe-se (sol)"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"seven","pos":"numeral","ipa":"/ˈsɛvən/","gloss":"sete"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-11-10', 'lesson-phrasal-b1-11', 10, 'phrasal', 'I''m all set.', 'Estou pronto.', '/aɪm ɔːl sɛt/', 'Informal. "All set" = tudo pronto.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"all","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"set","pos":"verb","ipa":"/sɛt/","gloss":"definir"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-phrasal-b1-12-01', 'lesson-phrasal-b1-12', 1, 'phrasal', 'They called off the game because of rain.', 'Cancelaram o jogo por causa da chuva.', '/ðeɪ kɔːld ɔːf ðə ɡeɪm bɪˈkɔːz ʌv reɪn/', '"Call off" = cancelar. Separável.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"called","pos":"verb","ipa":"/kɔːld/","gloss":"ligou, chamou"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"game","pos":"noun","ipa":"/ɡeɪm/","gloss":"jogo"},{"surface":"because","pos":"conjunction","ipa":"/bɪˈkɔːz/","gloss":"porque"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"rain","pos":"verb","ipa":"/reɪn/","gloss":"chover; chuva"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-12-02', 'lesson-phrasal-b1-12', 2, 'phrasal', 'I''ll call you back in a minute.', 'Te ligo de volta em um minuto.', '/aɪl kɔːl juː bæk ɪn ə ˈmɪnɪt/', '"Call back" = retornar a ligação.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"minute","pos":"noun","ipa":"/ˈmɪnɪt/","gloss":"minuto"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-12-03', 'lesson-phrasal-b1-12', 3, 'phrasal', 'The teacher called on me to answer.', 'O professor me chamou para responder.', '/ðə ˈtiːtʃər kɔːld ɑːn miː tuː ˈænsər/', '"Call on" = chamar alguém (em aula, reunião).', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"teacher","pos":"noun","ipa":"/ˈtiːtʃər/","gloss":"professor, professora"},{"surface":"called","pos":"verb","ipa":"/kɔːld/","gloss":"ligou, chamou"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"answer","pos":"noun","ipa":"/ˈænsər/","gloss":"resposta"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-12-04', 'lesson-phrasal-b1-12', 4, 'phrasal', 'Call me up when you are free.', 'Me liga quando estiver livre.', '/kɔːl miː ʌp wɛn juː ɑːr friː/', '"Call up" = telefonar. Informal.', '[]'::jsonb, '[{"surface":"Call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"free","pos":"adjective","ipa":"/friː/","gloss":"livre, disponível"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-12-05', 'lesson-phrasal-b1-12', 5, 'phrasal', 'Can you pick me up at eight?', 'Pode me buscar às oito?', '/kæn juː pɪk miː ʌp æt eɪt/', '"Pick up" = buscar alguém. Separável.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"pick","pos":"verb","ipa":"/pɪk/","gloss":"pegar (pick up)"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"eight","pos":"numeral","ipa":"/eɪt/","gloss":"oito"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-12-06', 'lesson-phrasal-b1-12', 6, 'phrasal', 'Pick up your toys.', 'Recolha seus brinquedos.', '/pɪk ʌp jʊr tɔɪz/', '"Pick up" = pegar do chão.', '[]'::jsonb, '[{"surface":"Pick","pos":"verb","ipa":"/pɪk/","gloss":"pegar (pick up)"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"toys","pos":"noun","ipa":"/tɔɪz/","gloss":"brinquedos"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-12-07', 'lesson-phrasal-b1-12', 7, 'phrasal', 'I picked up some Spanish in Mexico.', 'Aprendi um pouco de espanhol no México.', '/aɪ pɪkt ʌp sʌm ˈspænɪʃ ɪn ˈmɛksɪkoʊ/', '"Pick up" = aprender sem estudar formalmente.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"picked","pos":"verb","ipa":"/pɪkt/","gloss":"pegou, escolheu"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"Spanish","pos":"proper noun","ipa":"/ˈspænɪʃ/","gloss":"espanhol"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"Mexico","pos":"proper noun","ipa":"/ˈmɛksɪkoʊ/","gloss":"México"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-12-08', 'lesson-phrasal-b1-12', 8, 'phrasal', 'Help me pick out a gift.', 'Me ajuda a escolher um presente.', '/hɛlp miː pɪk aʊt ə ɡɪft/', '"Pick out" = escolher.', '[]'::jsonb, '[{"surface":"Help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"pick","pos":"verb","ipa":"/pɪk/","gloss":"pegar (pick up)"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"gift","pos":"noun","ipa":"/ɡɪft/","gloss":"presente"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-12-09', 'lesson-phrasal-b1-12', 9, 'phrasal', 'Sales are picking up.', 'As vendas estão melhorando.', '/seɪlz ɑːr ˈpɪkɪŋ ʌp/', '"Pick up" (sem objeto) = melhorar, aumentar.', '[]'::jsonb, '[{"surface":"Sales","pos":"noun","ipa":"/seɪlz/","gloss":"vendas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"picking","pos":"verb","ipa":"/ˈpɪkɪŋ/","gloss":"pegando; melhorando"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"}]'::jsonb, NULL, NULL),
  ('unit-phrasal-b1-12-10', 'lesson-phrasal-b1-12', 10, 'phrasal', 'Nobody picked up the phone.', 'Ninguém atendeu o telefone.', '/ˈnoʊbɑːdi pɪkt ʌp ðə foʊn/', '"Pick up the phone" = atender.', '[]'::jsonb, '[{"surface":"Nobody","pos":"pronoun","ipa":"/ˈnoʊbɑːdi/","gloss":"ninguém"},{"surface":"picked","pos":"verb","ipa":"/pɪkt/","gloss":"pegou, escolheu"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"}]'::jsonb, NULL, NULL)
